"""Blender setup script generated by ocean-generator.

Usage (from the folder this file lives in, or pass the manifest explicitly):

    blender --python ocean_blender.py
    blender --python ocean_blender.py -- /path/to/foam.json

What it does (fails loudly on any mismatch; it never guesses):
  1. verifies the foam PNG files against the SHA-256 hashes in foam.json,
  2. sets the scene frame rate from the manifest BEFORE importing,
  3. imports the GLB with smooth shading and checks the shape-key count,
  4. builds one water+foam material driven by the foam image sequence and assigns it to
     every imported mesh, and sets the scene frame range.

Mapping rules this script relies on (source-derived, see docs/whitecaps-spikes.md):
  * glTF v = 0 is the top of an image and Blender flips V on import, so the PNG needs no flip.
  * Foam image N (0-based) is shown on scene frame N: image-user frame_start = 0.
  * The foam image sequence is non-colour data with Repeat extension (the ocean tiles).
"""

import hashlib
import json
import os
import sys


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def load_and_verify(manifest_path):
    """Load foam.json and verify every referenced file. Returns (manifest, base_dir)."""
    manifest_path = os.path.abspath(manifest_path)
    base = os.path.dirname(manifest_path)
    with open(manifest_path, "r", encoding="utf-8") as f:
        m = json.load(f)

    if m.get("version") != 1:
        raise RuntimeError("unsupported foam.json version: %r" % (m.get("version"),))
    files = m["foam_files"]
    if len(files) != m["frame_count"]:
        raise RuntimeError(
            "manifest lists %d foam files but frame_count is %d" % (len(files), m["frame_count"])
        )
    for entry in files:
        path = os.path.join(base, entry["file"])
        if not os.path.isfile(path):
            raise RuntimeError("missing foam image: %s" % path)
        actual = sha256_file(path)
        if actual != entry["sha256"]:
            raise RuntimeError(
                "foam image changed since export: %s (sha256 %s, expected %s)"
                % (path, actual, entry["sha256"])
            )
    glb = m["glb"]
    glb_path = glb if os.path.isabs(glb) else os.path.normpath(os.path.join(base, glb))
    if not os.path.isfile(glb_path):
        raise RuntimeError("missing GLB: %s" % glb_path)
    return m, base, glb_path


def _first_input(node, names, value):
    """Set the first existing input of `names` (Blender renamed some sockets between versions)."""
    for name in names:
        if name in node.inputs:
            node.inputs[name].default_value = value
            return
    raise RuntimeError("none of the inputs %r exist on %s" % (names, node.bl_idname))


def _link_noise_breakup(nt, tex, mix):
    """Foam mask -> (mask + noise detail) -> crisp edge -> mix factor.

    The noise is evaluated in WORLD space so each tile gets different detail even though all
    tiles share one foam image. Noise only breaks up existing foam (it is multiplied by the
    mask), so foam never appears where the simulation put none.
    """
    geo = nt.nodes.new("ShaderNodeNewGeometry")
    noise = nt.nodes.new("ShaderNodeTexNoise")
    noise.inputs["Scale"].default_value = 6.0
    noise.inputs["Detail"].default_value = 8.0
    noise.inputs["Roughness"].default_value = 0.6
    scaled = nt.nodes.new("ShaderNodeMath")  # mask * (0.4 + noise)
    scaled.operation = "MULTIPLY"
    offset = nt.nodes.new("ShaderNodeMath")
    offset.operation = "ADD"
    offset.inputs[1].default_value = 0.4
    crisp = nt.nodes.new("ShaderNodeMapRange")
    crisp.inputs["From Min"].default_value = 0.35
    crisp.inputs["From Max"].default_value = 0.65
    crisp.clamp = True

    nt.links.new(geo.outputs["Position"], noise.inputs["Vector"])
    nt.links.new(noise.outputs["Fac"], offset.inputs[0])
    nt.links.new(tex.outputs["Color"], scaled.inputs[0])
    nt.links.new(offset.outputs["Value"], scaled.inputs[1])
    nt.links.new(scaled.outputs["Value"], crisp.inputs["Value"])
    nt.links.new(crisp.outputs["Result"], mix.inputs["Fac"])


def build_material(bpy, manifest, base):
    n = manifest["frame_count"]
    first = os.path.join(base, manifest["foam_files"][0]["file"])
    img = bpy.data.images.load(first, check_existing=False)
    img.colorspace_settings.name = "Non-Color"
    if n > 1:
        img.source = "SEQUENCE"

    mat = bpy.data.materials.new("OceanFoam")
    mat.use_nodes = True
    nt = mat.node_tree
    nt.nodes.clear()

    out = nt.nodes.new("ShaderNodeOutputMaterial")
    water = nt.nodes.new("ShaderNodeBsdfPrincipled")
    foam = nt.nodes.new("ShaderNodeBsdfPrincipled")
    mix = nt.nodes.new("ShaderNodeMixShader")
    uv = nt.nodes.new("ShaderNodeUVMap")
    tex = nt.nodes.new("ShaderNodeTexImage")

    water.inputs["Base Color"].default_value = (0.0, 0.3, 0.8, 1.0)
    water.inputs["Roughness"].default_value = 0.1
    water.inputs["IOR"].default_value = 1.33

    foam.inputs["Base Color"].default_value = (0.9, 0.9, 0.9, 1.0)
    foam.inputs["Roughness"].default_value = 0.7
    _first_input(foam, ["Specular IOR Level", "Specular"], 0.2)
    _first_input(foam, ["Subsurface Weight", "Subsurface"], 0.0)

    tex.image = img
    tex.interpolation = "Linear"
    tex.extension = "REPEAT"
    if n > 1:
        iu = tex.image_user
        iu.frame_duration = n
        iu.frame_start = 0  # scene frame 0 shows the first image
        iu.frame_offset = 0
        iu.use_auto_refresh = True
        iu.use_cyclic = False

    nt.links.new(uv.outputs["UV"], tex.inputs["Vector"])
    if manifest.get("noise_breakup", False):
        _link_noise_breakup(nt, tex, mix)
    else:
        nt.links.new(tex.outputs["Color"], mix.inputs["Fac"])
    nt.links.new(water.outputs["BSDF"], mix.inputs[1])
    nt.links.new(foam.outputs["BSDF"], mix.inputs[2])
    nt.links.new(mix.outputs["Shader"], out.inputs["Surface"])
    return mat


def main(manifest_path):
    import bpy  # only available inside Blender

    manifest, base, glb_path = load_and_verify(manifest_path)
    n = manifest["frame_count"]

    # Frame rate first, so the importer maps keyframe seconds to the right frames.
    fps = float(manifest["fps"])
    scene = bpy.context.scene
    scene.render.fps = int(round(fps))
    scene.render.fps_base = round(fps) / fps

    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=glb_path, import_shading="SMOOTH")
    meshes = [o for o in bpy.data.objects if o not in before and o.type == "MESH"]
    if not meshes:
        raise RuntimeError("the GLB import produced no mesh objects")

    expected_keys = manifest.get("shape_keys", 0)
    for obj in meshes:
        keys = obj.data.shape_keys.key_blocks if obj.data.shape_keys else []
        count = len(keys) - (1 if len(keys) and keys[0].name == "Basis" else 0)
        if count != expected_keys:
            raise RuntimeError(
                "%s has %d shape keys but the manifest expects %d" % (obj.name, count, expected_keys)
            )

    mat = build_material(bpy, manifest, base)
    for obj in meshes:
        obj.data.materials.clear()
        obj.data.materials.append(mat)

    scene.frame_start = 0
    scene.frame_end = max(n - 1, 0)
    scene.frame_set(0)
    print("ocean_blender: %d tile(s), %d foam frame(s), fps %s" % (len(meshes), n, fps))


if __name__ == "__main__":
    argv = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else []
    default = os.path.join(os.path.dirname(os.path.abspath(__file__)), "foam.json")
    main(argv[0] if argv else default)
